const fs = require('fs');
const path = require('path');
const dotenv = require('dotenv');

// Load .env.test to get the list of required secret names
const envTestPath = path.join(__dirname, '.env.test');
let requiredSecrets = [];
if (fs.existsSync(envTestPath)) {
  const envTestContent = fs.readFileSync(envTestPath, 'utf8');
  requiredSecrets = envTestContent
    .split('\n')
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('#'))
    .map(line => line.split('=')[0]);
}

// Mock AWS Secrets Manager for demo - in real app use @aws-sdk/client-secrets-manager
const mockSecretsManager = {
  getSecretValue: async ({ SecretId }) => {
    // In real AWS, this would fetch from Secrets Manager
    // For demo, simulate with known values or error
    const simulatedSecrets = {
      'DATABASE_URL': process.env.DATABASE_URL || 'postgres://admin:mock-db-password@db.internal:5432/production',
      'ANTHROPIC_API_KEY': process.env.ANTHROPIC_API_KEY || 'REDACTED_ANTHROPIC_KEY',
      'STRIPE_SECRET_KEY': process.env.STRIPE_SECRET_KEY || 'REDACTED_STRIPE_LIVE',
      'LOGFIRE_TOKEN': process.env.LOGFIRE_TOKEN || 'mock-logfire-token-abcde'
    };

    if (simulatedSecrets[SecretId]) {
      return { SecretString: simulatedSecrets[SecretId] };
    }
    throw new Error(`Secret ${SecretId} not found in AWS`);
  }
};

// Cache for fetched secrets
const cache = new Map();

/**
 * Get a secret by name
 * Tries AWS Secrets Manager first, falls back to local .env if not found or in dev
 * @param {string} name - The secret name
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  // Return from cache if available
  if (cache.has(name)) {
    return cache.get(name);
  }

  let secretValue = null;
  const isTestEnv = process.env.NODE_ENV === 'test';

  // Try AWS Secrets Manager unless in test environment
  if (!isTestEnv) {
    try {
      const response = await mockSecretsManager.getSecretValue({ SecretId: name });
      secretValue = response.SecretString;
    } catch (error) {
      console.warn(`Could not fetch secret ${name} from AWS Secrets Manager:`, error.message);
    }
  }

  // Fallback to local environment variables (from .env files)
  if (!secretValue) {
    secretValue = process.env[name];
  }

  // Final fallback: read from .env.test directly if available
  if (!secretValue && requiredSecrets.includes(name)) {
    try {
      const envTest = dotenv.config({ path: '.env.test' }).parsed;
      secretValue = envTest[name];
    } catch (error) {
      console.warn(`Could not load ${name} from .env.test:`, error.message);
    }
  }

  if (!secretValue) {
    throw new Error(`Secret ${name} not found in AWS, environment, or .env.test`);
  }

  // Cache the value
  cache.set(name, secretValue);
  return secretValue;
}

module.exports = { getSecret };

