// secrets.js
// Module to handle secret retrieval from AWS Secrets Manager with .env.test fallback

const fs = require('fs');
const dotenv = require('dotenv');
const AWS = require('aws-sdk');

// Cache for loaded .env.test secrets
const localSecrets = {};

// Initialize AWS SDK
const secretsManager = new AWS.SecretsManager({ region: process.env.AWS_REGION || 'us-east-1' });

// Load secrets from .env.test into cache
function loadLocalSecrets() {
  if (Object.keys(localSecrets).length === 0) {
    const envTest = dotenv.parse(fs.readFileSync('.env.test', 'utf8'));
    for (const [key, value] of Object.entries(envTest)) {
      localSecrets[key] = value;
    }
  }
}

/**
 * Get a secret value by name
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  // Ensure local secrets are loaded
  loadLocalSecrets();

  // In development, use .env.test fallback
  if (process.env.NODE_ENV !== 'production') {
    if (localSecrets.hasOwnProperty(name)) {
      console.log(`Using local fallback for secret: ${name}`);
      return localSecrets[name];
    }
    throw new Error(`Secret not found locally: ${name}`);
  }

  // In production, fetch from AWS Secrets Manager
  try {
    const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
    if (data.SecretString) {
      return data.SecretString;
    } else if (data.SecretBinary) {
      return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }
    throw new Error('Secret value is empty');
  } catch (error) {
    console.error(`Failed to retrieve secret ${name} from AWS Secrets Manager:`, error);
    throw error;
  }
}

module.exports = { getSecret };

