const dotenv = require('dotenv');
const fs = require('fs');
const path = require('path');

// Load .env.test for development fallback
const envTestPath = path.resolve(process.cwd(), '.env.test');
if (fs.existsSync(envTestPath)) {
  dotenv.config({ path: envTestPath });
}

// Extract secret names from .env.test
const getSecretNames = () => {
  if (!fs.existsSync(envTestPath)) {
    return [];
  }

  const envContent = fs.readFileSync(envTestPath, 'utf8');
  const secretNames = [];

  // Extract variable names (everything before the =)
  const lines = envContent.split('\n');
  for (const line of lines) {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (trimmed && !trimmed.startsWith('#') && trimmed.includes('=')) {
      const name = trimmed.split('=')[0].trim();
      secretNames.push(name);
    }
  }

  return secretNames;
};

// Get all secret names from .env.test
const SECRET_NAMES = getSecretNames();

// Initialize AWS SDK if available
let secretsManager;
try {
  const AWS = require('aws-sdk');
  secretsManager = new AWS.SecretsManager();
} catch (err) {
  console.warn('AWS SDK not available - running in local development mode');
}

/**
 * Get a secret value by name
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string>} - The secret value
 */
const getSecret = async (name) => {
  // First check if we have the secret in environment variables (from .env.test)
  if (process.env[name]) {
    console.debug(`Using local environment variable for ${name}`);
    return process.env[name];
  }

  // If we're not in a local development environment and have AWS SDK available
  if (secretsManager && process.env.NODE_ENV !== 'development') {
    try {
      console.debug(`Fetching ${name} from AWS Secrets Manager`);
      const data = await secretsManager.getSecretValue({ SecretId: name }).promise();

      if (data.SecretString) {
        return data.SecretString;
      } else if (data.SecretBinary) {
        // For binary secrets, decode from base64
        return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
      }
    } catch (error) {
      console.error(`Failed to retrieve ${name} from AWS Secrets Manager:`, error.message);
      throw error;
    }
  }

  // If we get here, we couldn't retrieve the secret
  throw new Error(`Secret not found: ${name}. Ensure it exists in .env.test or AWS Secrets Manager.`);
};

module.exports = { getSecret, SECRET_NAMES };

