const dotenv = require('dotenv');
const fs = require('fs');
const path = require('path');

// Load environment variables from .env.test for fallback
const envConfig = dotenv.parse(fs.readFileSync(path.resolve(__dirname, '../.env.test')));

const secretsManager = new AWS.SecretsManager();

/**
 * Fetches a secret by name from AWS Secrets Manager, falling back to .env.test if not found.
 * @param {string} name - The name of the secret to retrieve.
 * @returns {Promise<string>} The secret value.
 */
async function getSecret(name) {
  // First, try to fetch from AWS Secrets Manager
  try {
    const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
    if (data.SecretString) {
      const secretObject = JSON.parse(data.SecretString);
      // Assume the secret is stored as a key-value pair where the key is the same as the env var name
      return secretObject[name];
    }
  } catch (error) {
    if (error.code !== 'ResourceNotFoundException') {
      console.warn(`Error fetching secret '${name}' from AWS Secrets Manager:`, error.message);
    }
    // Fall back to .env.test values if the secret doesn't exist in AWS or there's an error
    if (envConfig[name]) {
      console.log(`Falling back to .env.test value for secret: ${name}`);
      return envConfig[name];
    } else {
      throw new Error(`Secret '${name}' not found in AWS Secrets Manager or .env.test`);
    }
  }
}

module.exports = { getSecret };

