// secrets.js
// Module for managing application secrets with AWS Secrets Manager and .env.test fallback

const AWS = require('aws-sdk');
const dotenv = require('dotenv');

// Cache for fetched secrets
const cache = new Map();

// Parse .env.test to get available secret names
const envTest = dotenv.parse(require('fs').readFileSync('.env.test'));
const localSecrets = Object.keys(envTest);

// Initialize AWS Secrets Manager
const secretsManager = new AWS.SecretsManager();

/**
 * Get a secret value by name
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  // Return from cache if available
  if (cache.has(name)) {
    return cache.get(name);
  }

  let value = null;

  // Try to get from AWS Secrets Manager
  if (process.env.NODE_ENV !== 'development') {
    try {
      const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
      value = data.SecretString;
      // If the secret is a JSON string, parse it and extract the value
      try {
        const parsed = JSON.parse(value);
        if (typeof parsed === 'object' && parsed !== null) {
          value = parsed[name] || Object.values(parsed)[0]; // Fallback to first value
        }
      } catch (e) {
        // Value is not JSON, use as-is
      }
    } catch (error) {
      console.warn(`Failed to retrieve secret '${name}' from AWS Secrets Manager:`, error.message);
    }
  }

  // Fallback to .env.test in development
  if (value === null && localSecrets.includes(name)) {
    value = envTest[name];
    console.debug(`Using local fallback for secret '${name}'`);
  }

  if (value === null) {
    throw new Error(`Secret '${name}' not found in AWS Secrets Manager or .env.test`);
  }

  // Cache the value
  cache.set(name, value);
  return value;
}

module.exports = { getSecret };

