try {
  const dotenvContent = fs.readFileSync(dotenvPath, 'utf8');
  requiredSecrets = dotenvContent
    .split('\n')
    .map(line => line.trim())
    .filter(line => line && !line.startsWith('#'))
    .map(line => line.split('=')[0]);
} catch (error) {
  console.warn('Could not read .env.test for secret names:', error.message);
}

const client = new SecretsManagerClient({});

/**
 * Get a secret value by name.
 * Attempts to fetch from AWS Secrets Manager first.
 * Falls back to .env.test file if not found or in case of error (e.g., local development).
 * Throws an error if the secret is not found in both places.
 * 
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  // Validate requested secret name
  if (!requiredSecrets.includes(name)) {
    throw new Error(`Requested secret "${name}" is not defined in .env.test`);
  }

  // Try AWS Secrets Manager first
  try {
    const command = new GetSecretValueCommand({ SecretId: name });
    const response = await client.send(command);
    return response.SecretString;
  } catch (error) {
    if (error.name === 'ResourceNotFoundException' || error.name === 'AccessDeniedException') {
      // Fall back to .env.test
      console.warn(`AWS Secrets Manager ${error.name}: ${error.message}. Falling back to .env.test.`);
    } else {
      console.warn(`AWS Secrets Manager error: ${error.message}. Falling back to .env.test.`);
    }
  }

  // Fallback: Read from .env.test
  try {
    const dotenvContent = fs.readFileSync(dotenvPath, 'utf8');
    const regex = new RegExp(`^${name}=(.*)$`, 'm');
    const match = dotenvContent.match(regex);
    if (match) {
      return match[1];
    }
  } catch (error) {
    // Ignore file read errors in fallback
  }

  throw new Error(`Secret "${name}" not found in AWS Secrets Manager or .env.test`);
}

