// secrets.js
// Module for loading secrets from AWS Secrets Manager with local .env.test fallback

const fs = require('fs');
const path = require('path');
require('dotenv').config({ path: path.resolve(process.cwd(), '.env.test') });

// Check if running in AWS (Lambda, EC2, etc.)
const isRunningInAWS = () => {
  return process.env.AWS_EXECUTION_ENV || process.env.EC2_INSTANCE_ID || process.env.AWS_LAMBDA_FUNCTION_NAME;
};

// Lazy-initialized Secrets Manager client
let secretsManager;
const getSecretsManager = () => {
  if (!secretsManager) {
    const AWS = require('aws-sdk');
    secretsManager = new AWS.SecretsManager({ region: process.env.AWS_REGION || 'us-east-1' });
  }
  return secretsManager;
};

// Cache for fetched secrets
const secretCache = new Map();

// Read required secret names from .env.test (keys only)
const requiredSecrets = [];
try {
  const envTestPath = path.resolve(process.cwd(), '.env.test');
  if (fs.existsSync(envTestPath)) {
    const envContent = fs.readFileSync(envTestPath, 'utf-8');
    const envLines = envContent.split('\n').filter(line => line.trim() && !line.startsWith('#'));
    for (const line of envLines) {
      const match = line.trim().match(/^([^=]+)=/);
      if (match) {
        requiredSecrets.push(match[1].trim());
      }
    }
  }
} catch (err) {
  console.warn('Could not read .env.test for secret names:', err.message);
}

/**
 * Get a secret value by name.
 * Attempts AWS Secrets Manager first if running in AWS, falls back to .env.test.
 * Caches results to avoid repeated calls.
 * 
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string|null>} The secret value, or null if not found
 */
async function getSecret(name) {
  // Return cached value if available
  if (secretCache.has(name)) {
    return secretCache.get(name);
  }

  let value = null;

  // Only try AWS Secrets Manager if running in AWS
  if (isRunningInAWS()) {
    try {
      const secretsManager = getSecretsManager();
      const result = await secretsManager.getSecretValue({ SecretId: name }).promise();
      value = result.SecretString;
      console.log(`Loaded secret '${name}' from AWS Secrets Manager`);
    } catch (err) {
      console.warn(`Could not load secret '${name}' from AWS Secrets Manager:`, err.message);
    }
  }

  // Fallback to .env if value not retrieved from AWS
  if (value === null) {
    value = process.env[name];
    if (value) {
      console.log(`Loaded secret '${name}' from .env.test fallback`);
    } else {
      console.warn(`Secret '${name}' not found in AWS or .env.test`);
    }
  }

  // Cache the value (even if null)
  secretCache.set(name, value);
  return value;
}

module.exports = { getSecret, requiredSecrets };

