const fs = require('fs');
const dotenv = require('dotenv');

// Load .env.test to get the list of required secrets
const envTestPath = '.env.test';
const envTestRaw = fs.readFileSync(envTestPath, 'utf8');
const envTest = dotenv.parse(envTestRaw);

// Extract secret names from .env.test
const secretNames = Object.keys(envTest);

// AWS SDK (conditionally required to avoid runtime issues if not available)
let AWS;
try {
  AWS = require('aws-sdk');
} catch (err) {
  // AWS SDK not available, likely in non-AWS dev environment
}

// Cache for fetched secrets
const cache = {};

/**
 * Fetch a secret by name, trying AWS Secrets Manager first, then falling back to .env.test
 * @param {string} name - The name of the secret to fetch
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  if (!secretNames.includes(name)) {
    throw new Error(`Secret name '${name}' is not defined in .env.test`);
  }

  // Return from cache if available
  if (cache[name]) {
    return cache[name];
  }

  // Try AWS Secrets Manager first
  if (AWS) {
    try {
      const client = new AWS.SecretsManager();
      const data = await client.getSecretValue({ SecretId: name }).promise();
      const value = data.SecretString;
      cache[name] = value;
      return value;
    } catch (error) {
      console.warn(`Failed to fetch secret '${name}' from AWS Secrets Manager:`, error.message);
    }
  }

  // Fallback to .env.test
  const fallbackValue = envTest[name];
  if (fallbackValue) {
    cache[name] = fallbackValue;
    return fallbackValue;
  }

  throw new Error(`Secret '${name}' not found in AWS Secrets Manager or .env.test`);
}

module.exports = { getSecret, secretNames };

