require('dotenv').config({ path: '.env.test' });

const AWS = require('aws-sdk');

// Initialize AWS SDK (will use local credentials in development)
const secretsManager = new AWS.SecretsManager();

// Extract secret names from .env.test file
const fs = require('fs');
const path = require('path');

// Read the .env.test file and extract variable names
const envTestContent = fs.readFileSync(path.resolve('.env.test'), 'utf8');
const requiredSecrets = envTestContent
  .split('\n')
  .map(line => line.trim())
  .filter(line => line && !line.startsWith('#') && line.includes('='))
  .map(line => line.split('=')[0]);

/**
 * Get a secret value by name
 * @param {string} name - The name of the secret
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  // First check if we're in development and have the secret in .env.test
  if (process.env.NODE_ENV !== 'production') {
    const localValue = process.env[name];
    if (localValue) {
      console.log(`Using local value for secret '${name}' from .env.test`);
      return localValue;
    }
  }

  // Otherwise, fetch from AWS Secrets Manager
  try {
    console.log(`Fetching secret '${name}' from AWS Secrets Manager...`);
    const response = await secretsManager.getSecretValue({ SecretId: name }).promise();
    return response.SecretString;
  } catch (error) {
    if (error.code === 'ResourceNotFoundException' || error.code === 'AccessDeniedException') {
      // If the secret doesn't exist in AWS, check if we have it locally
      const fallbackValue = process.env[name];
      if (fallbackValue) {
        console.log(`AWS secret '${name}' not found or access denied. Using fallback from .env.test`);
        return fallbackValue;
      }
    }
    throw new Error(`Failed to retrieve secret '${name}': ${error.message}`);
  }
}

module.exports = {
  getSecret,
  requiredSecrets
};

