const fs = require('fs');
const dotenv = require('dotenv');

// Load local .env.test for development and to read secret keys
let localSecrets = {};
try {
  const envConfig = dotenv.parse(fs.readFileSync('.env.test'));
  localSecrets = envConfig;
} catch (err) {
  console.warn('Could not load .env.test, proceeding with AWS only: ', err.message);
}

// Initialize AWS SDK
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

/**
 * getSecret - Retrieves a secret value by name.
 * Tries AWS Secrets Manager first, falls back to .env.test if not found or in dev.
 * @param {string} name - The name/key of the secret
 * @returns {Promise<string|null>}
 */
async function getSecret(name) {
  // First, check local .env.test for instant access during development
  if (localSecrets[name]) {
    return localSecrets[name];
  }

  // If not in local, try AWS Secrets Manager
  try {
    const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
    if (data.SecretString) {
      return data.SecretString;
    }
  } catch (err) {
    if (err.code === 'ResourceNotFoundException') {
      console.warn(`Secret '${name}' not found in AWS Secrets Manager`);
    } else {
      console.error(`Error fetching secret '${name}' from AWS:`, err);
    }
  }

  // Fallback: return null if not found anywhere
  return null;
}

module.exports = { getSecret };

