// secrets.js
// AWS Secrets Manager with local .env.test fallback

const fs = require('fs');
const path = require('path');
const dotenv = require('dotenv');

// Load required secret names from .env.test
const envTestPath = path.join(__dirname, '.env.test');
const envTest = dotenv.parse(fs.readFileSync(envTestPath));
const requiredSecrets = Object.keys(envTest);

// Initialize AWS SDK if available
let secretsManager;
try {
  const AWS = require('aws-sdk');
  secretsManager = new AWS.SecretsManager({ region: process.env.AWS_REGION || 'us-east-1' });
} catch (err) {
  console.warn('AWS SDK not available, running in local fallback mode');
}

// Cache for fetched secrets
const cache = new Map();

/**
 * Get a secret value by name
 * @param {string} name - The name of the secret
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name) {
  if (!requiredSecrets.includes(name)) {
    throw new Error(`Unknown secret: ${name}. Please add it to .env.test first.`);
  }

  // Return from cache if available
  if (cache.has(name)) {
    return cache.get(name);
  }

  // Try AWS Secrets Manager in production
  if (secretsManager && process.env.NODE_ENV === 'production') {
    try {
      const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
      const value = data.SecretString;
      cache.set(name, value);
      return value;
    } catch (error) {
      console.error(`Failed to fetch secret ${name} from AWS:`, error.message);
      throw error;
    }
  }

  // Fallback to .env.test for local development
  const value = envTest[name];
  if (!value) {
    throw new Error(`Secret ${name} not found in .env.test`);
  }

  cache.set(name, value);
  return value;
}

module.exports = { getSecret, requiredSecrets };

