const fs = require('fs');
const dotenv = require('dotenv');
const AWS = require('aws-sdk');

// Load the test environment variables to know which secrets we need
const envConfig = dotenv.parse(fs.readFileSync('.env.test'));
const requiredSecrets = Object.keys(envConfig);

// Initialize AWS Secrets Manager
const secretsManager = new AWS.SecretsManager();

/**
 * Get a secret by name.
 * Attempts to fetch from AWS Secrets Manager first.
 * Falls back to .env.test values if not found (for local development).
 * 
 * @param {string} name - The name of the secret to retrieve
 * @returns {Promise<string>} The secret value
 * @throws {Error} If the secret cannot be retrieved and no fallback exists
 */
async function getSecret(name) {
  if (!requiredSecrets.includes(name)) {
    throw new Error(`Requested secret "${name}" is not defined in .env.test`);
  }

  // Try to get from AWS Secrets Manager
  try {
    const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
    if (data.SecretString) {
      return data.SecretString;
    }
    if (data.SecretBinary) {
      return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }
  } catch (error) {
    if (error.code !== 'ResourceNotFoundException') {
      console.warn(`Warning: Failed to retrieve secret "${name}" from AWS Secrets Manager:`, error.message);
    }
    // Fall through to fallback
  }

  // Fallback to .env.test value for development
  if (envConfig[name]) {
    console.warn(`Using fallback value for secret "${name}" from .env.test`);
    return envConfig[name];
  }

  throw new Error(`Secret "${name}" not found in AWS Secrets Manager and no fallback available`);
}

module.exports = { getSecret };

